import { z } from 'zod';
import { DomainError, notImplemented, type UseCase, type UseCaseContext } from '@agentic-ddd/core';
import { AgentUseCase } from '@agentic-ddd/decorators';
import { TaskCompleted } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';

export const completeTaskInput = z.object({ task_id: z.string().min(1) });
export const completeTaskOutput = z.object({ task_id: z.string(), status: z.literal('completed') });
export type CompleteTaskInput = z.infer<typeof completeTaskInput>;
export type CompleteTaskOutput = z.infer<typeof completeTaskOutput>;

@AgentUseCase({ name: 'complete_task', description: 'Carrega, conclui, salva e publica a tarefa; id ausente falha com TASK_NOT_FOUND.', whenToUse: 'Quando o usuário terminou uma tarefa.', whenNotToUse: 'Para criar uma nova tarefa.', input: completeTaskInput, output: completeTaskOutput, uses: ['method:Task.complete'], emits: [TaskCompleted] })
export class CompleteTask implements UseCase<CompleteTaskInput, CompleteTaskOutput> {
  constructor(private readonly tasks: TaskRepository) {}
  async execute(input: CompleteTaskInput, ctx: UseCaseContext): Promise<CompleteTaskOutput> {
    const task = await this.tasks.findById(input.task_id);
    if (!task) {
      throw new DomainError('TASK_NOT_FOUND', 'A tarefa não foi encontrada.');
    }
    task.complete();
    await this.tasks.save(task);
    await ctx.publish(task.pullEvents());
    return { task_id: task.id, status: 'completed' };






  }
}

import { expect, mock, test } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers, createTestContext } from '@agentic-ddd/testing';
import { CompleteTask } from '../application/complete-task';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'carrega t1, salva completed antes de publicar TaskCompleted e retorna o contrato'), async () => {
  const persisted = new InMemoryTaskRepository();
  const task = Task.create('t1', 'Concluir tarefa');
  task.pullEvents();
  await persisted.save(task);
  const operations: string[] = [];
  const repository = {
    async findById(id: string) {
      operations.push(`load:${id}`);
      return persisted.findById(id);
    },
    async save(value: Task) {
      await Promise.resolve();
      await persisted.save(value);
      operations.push(`save:${value.status}`);
    },
  };
  const context = createTestContext();
  const output = await new CompleteTask(repository).execute({ task_id: 't1' }, {
    ...context,
    async publish(events) {
      operations.push('publish');
      await context.publish(events);
    },
  });

  expect(output).toEqual({ task_id: 't1', status: 'completed' });
  expect(operations).toEqual(['load:t1', 'save:completed', 'publish']);
  expect((await persisted.findById('t1'))?.status).toBe('completed');
  expect(context.published).toHaveLength(1);
  expect(context.published[0]).toBeInstanceOf(TaskCompleted);
  expect(context.published[0]!.payload).toEqual({ taskId: 't1' });
  expect(task.pullEvents()).toEqual([]);
});

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'rejeita id ausente com TASK_NOT_FOUND sem salvar ou publicar'), async () => {
  const repository = {
    findById: mock(async (_id: string): Promise<Task | null> => null),
    save: mock(async (_task: Task) => {}),
  };
  const context = createTestContext();
  const publish = mock(context.publish);
  const execution = new CompleteTask(repository).execute({ task_id: 'inexistente' }, {
    ...context, publish,
  });

  await expect(execution).rejects.toBeInstanceOf(DomainError);
  await expect(execution).rejects.toMatchObject({ code: 'TASK_NOT_FOUND' });
  expect(repository.findById).toHaveBeenCalledWith('inexistente');
  expect(repository.save).not.toHaveBeenCalled();
  expect(publish).not.toHaveBeenCalled();
  expect(context.published).toEqual([]);
});

test(covers([
  'usecase:complete_task',
], 'propaga TASK_ALREADY_COMPLETED sem salvar ou publicar novamente'), async () => {
  const task = Task.create('t1', 'Concluir tarefa');
  task.complete();
  task.pullEvents();
  const repository = {
    findById: mock(async (_id: string) => task),
    save: mock(async (_task: Task) => {}),
  };
  const context = createTestContext();
  const publish = mock(context.publish);
  const execution = new CompleteTask(repository).execute({ task_id: 't1' }, {
    ...context, publish,
  });

  await expect(execution).rejects.toBeInstanceOf(DomainError);
  await expect(execution).rejects.toMatchObject({ code: 'TASK_ALREADY_COMPLETED' });
  expect(task.status).toBe('completed');
  expect(repository.save).not.toHaveBeenCalled();
  expect(publish).not.toHaveBeenCalled();
  expect(task.pullEvents()).toEqual([]);
});

test(covers([
  'usecase:complete_task',
], 'aguarda gravação e propaga sua falha sem publicar eventos'), async () => {
  const task = Task.create('t1', 'Concluir tarefa');
  task.pullEvents();
  const failure = new Error('Falha ao salvar');
  const repository = {
    async findById(_id: string) { return task; },
    async save(_task: Task) {
      await Promise.resolve();
      throw failure;
    },
  };
  const context = createTestContext();
  const publish = mock(context.publish);

  await expect(new CompleteTask(repository).execute({ task_id: 't1' }, {
    ...context, publish,
  })).rejects.toBe(failure);
  expect(publish).not.toHaveBeenCalled();
  expect(context.published).toEqual([]);
});
